example_item.example_item_data:
A = sparse([4 1 0; 2 3 1; 0 1 2]);
[L, U] = ilu(A)
full(L * U)

A = sparse(single([0 1 + 2i; 3 - 1i 4]));
opts.type = 'ilutp';
opts.droptol = 0;
[L, U, P] = ilu(A, opts);
full(P * A - L * U)

A = sparse([0.2 1; 1 1]);
opts.type = 'ilutp';
opts.droptol = 0;
opts.fillfactor = 10;
opts.thresh = 0.25;
[L, U, P] = ilu(A, opts);
full(P * A - L * U)
